 * { box-sizing: border-box; margin: 0; padding: 0; }
 body { font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', sans-serif; background: #fff; color: #111; line-height: 1.6; word-break: keep-all; overflow-wrap: break-word; }
 .wrapper { max-width: 800px; margin: 0 auto; border: 1px solid #e5e7eb; border-radius: 12px; overflow: hidden; word-break: keep-all; overflow-wrap: break-word; }
 .header-bar { background: #E8384F; padding: 1rem 2rem; display: flex; align-items: center; gap: 12px; }
 .header-bar .logo { font-size: 18px; font-weight: 600; color: #fff; letter-spacing: -0.01em; }
 .header-bar .logo span { font-weight: 400; opacity: 0.85; font-size: 13px; margin-left: 8px; }
 .section { padding: 2.5rem 2rem; border-bottom: 1px solid #f0f0f0; }
 .section:last-child { border-bottom: none; }
 .eyebrow { font-size: 12px; color: #888; letter-spacing: 0.05em; text-transform: uppercase; margin-bottom: 8px; }
 .headline { font-size: 22px; font-weight: 600; color: #111; line-height: 1.35; margin-bottom: 1rem; }
 .body-text { font-size: 14px; color: #555; line-height: 1.75; }
 .intro-box { background: #f9f9f9; border-left: 3px solid #E8384F; border-radius: 0 8px 8px 0; padding: 1rem 1.25rem; margin-top: 1rem; }
 .tag-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 0.75rem; }
 .tag { font-size: 12px; background: #f5f5f5; color: #555; padding: 4px 10px; border-radius: 999px; border: 1px solid #e5e5e5; }
 .tag.accent { background: #FBEAF0; color: #993556; border-color: #F4C0D1; }
 .stat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 1.5rem; }
 .stat-card { background: #f9f9f9; border-radius: 10px; padding: 1.25rem 1rem; text-align: center; }
 .stat-num { font-size: 24px; font-weight: 700; color: #E8384F; line-height: 1.2; margin-bottom: 4px; }
 .stat-label { font-size: 12px; color: #888; line-height: 1.5; }
 .reason-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 1.5rem; }
 .reason-card { background: #fff; border: 1px solid #eee; border-radius: 10px; padding: 1.25rem 1rem; }
 .reason-num { font-size: 11px; font-weight: 600; color: #E8384F; border: 1px solid #E8384F; border-radius: 4px; display: inline-block; padding: 1px 6px; margin-bottom: 10px; }
 .reason-title { font-size: 14px; font-weight: 600; color: #111; margin-bottom: 8px; line-height: 1.4; }
 .reason-body { font-size: 12px; color: #666; line-height: 1.6; }
 .placement-img { width: 100%; border-radius: 8px; margin-top: 1.25rem; display: block; }
 .targeting-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 1.5rem; }
 .targeting-card { background: #fff; border: 1px solid #eee; border-radius: 10px; padding: 1.25rem; }
 .targeting-icon-wrap { width: 40px; height: 40px; border-radius: 50%; background: #FBEAF0; display: flex; align-items: center; justify-content: center; margin-bottom: 10px; }
 .targeting-icon-wrap svg { width: 20px; height: 20px; stroke: #E8384F; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
 .targeting-title { font-size: 14px; font-weight: 600; color: #111; margin-bottom: 8px; }
 .targeting-list { list-style: none; }
 .targeting-list li { font-size: 12px; color: #666; padding: 3px 0; display: flex; align-items: flex-start; gap: 6px; line-height: 1.5; }
 .targeting-list li::before { content: '·'; color: #E8384F; font-weight: 700; flex-shrink: 0; margin-top: 1px; }
 .fit-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-top: 1rem; }
 .fit-item { display: flex; align-items: flex-start; gap: 10px; padding: 0.75rem; background: #fff; border-radius: 8px; border: 1px solid #eee; }
 .fit-item svg { width: 18px; height: 18px; stroke: #E8384F; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; margin-top: 1px; }
 .fit-item span { font-size: 13px; color: #222; line-height: 1.5; }
